    if (target < 0 || target > (int64_t)m->cp_len || (!allow_end && target == (int64_t)m->cp_len)) {
        *ok = false;
        return 0u;
    }
    if (m->ascii) {
        *ok = true;
        return (size_t)target;
    }
    if (target == (int64_t)m->cp_len) {
        *ok = true;
        return (size_t)m->byte_len;
    }
    const char *s = m->s;
    size_t blen = (size_t)m->byte_len;
